import {rpc,fileUrl,identity,uploadBrowserFile} from '../host-shim.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const GENERIC_TOOL_SPECS=Object.freeze({
 'image-wash':{title:'质感增强',kind:'image',count:1,description:'通过你配置的图片模型调整色调与细节，保持主体和构图。',prompt:'增强原图的自然材质、光影层次和细节。保持主体、构图和原图尺寸，不添加物品。'},
 'image-upscale':{title:'图像放大',kind:'image',count:1,description:'通过图片模型放大与补充细节；需要声明图片输入和输出尺寸参数的 API。',prompt:'高保真放大原图，保持主体和构图，补充自然纹理，避免改变原图内容。'},
 product:{title:'商品合图',kind:'image',count:2,description:'第一张为人物或背景，第二张为商品。模型须支持至少两张参考图。',prompt:'将第二张参考的商品自然融入第一张人物或场景，保持人物和商品身份、材质与文字。'},
 relight:{title:'光照重置',kind:'video',count:2,video:true,description:'选择源视频与光照参考图。仅向声明视频和图片输入的模型提交，不以首帧替代整个视频。',prompt:'保持源视频的人物、动作、镜头运动和时序，按参考图重设计光照、色彩与氛围。'},
 motion:{title:'动作迁移',kind:'video',count:2,video:true,description:'选择角色图和动作视频。模型须同时支持视频与图片参考。',prompt:'使用角色图中的同一角色，复现动作视频的姿态、动作节奏和运动轨迹，保持角色身份。'},
 layers:{title:'图层拆分',kind:'image',count:1,layers:true,description:'为每一层单独生成可编辑素材。透明背景输出取决于所接模型；下载前可查看真实原件。',prompt:'将原图拆为可独立编辑的图层，保持各元素在原画幅中的位置，其他区域透明。'},
 'cutout-repair':{title:'智能抠补',kind:'image',count:1,mask:true,description:'以原图与选区蒙版进行抠图或补全。仅向明确映射蒙版的模型提交。',prompt:'按蒙版提取或补全选中主体，边缘自然，保留原主体的身份和细节。'},
 'local-edit':{title:'局部修改',kind:'image',count:1,mask:true,description:'在图上拖出选区，只修改选中部分。模型必须配置蒙版输入映射。',prompt:'只修改蒙版标记区域，保持其他区域、人物身份、构图与光照不变。'}
});
export async function mountGenericTool(host,{toolId,onBack}){
 const spec=GENERIC_TOOL_SPECS[toolId];if(!spec)throw Error('未知创作工具');let disposed=false,busy=false,selection=null,maskAsset=null,lastResult=null;const node=document.createElement('section');node.className='dsh-generic-tool';node.dataset.toolId=toolId;node.innerHTML=`<header><button data-back aria-label="返回工具">← 返回工具</button><h1>${spec.title}</h1><p>${spec.description}</p></header><div class="dsh-generic-body"><aside><h2>输入素材</h2><p>原件来自 DSH 统一素材库；本机上传后先入统一库。</p><div data-inputs></div><label>上传原件 <input data-upload type="file" ${spec.video?'accept="image/*,video/*"':'accept="image/*"'} multiple></label><h2>生成设置</h2><label>模型 <select data-model></select></label><p data-capability role="status"></p><label>你的要求 <textarea data-prompt>${spec.prompt}</textarea></label>${spec.layers?'<label>图层名称（每行一层）<textarea data-layers>背景\n主体\n前景</textarea></label>':''}${toolId==='image-upscale'?'<label>目标宽度 <input data-width type="number" value="2048" min="64" max="8192"></label><label>目标高度 <input data-height type="number" value="2048" min="64" max="8192"></label>':''}<details><summary>已声明的 API 参数</summary><div data-parameters></div></details><button data-run disabled>开始${spec.kind==='video'?'生成视频':'处理'}</button><button data-stop hidden>停止本地等待</button><p data-status role="status"></p></aside><main><h2>${spec.mask?'拖动选择修改区域':'原件与结果预览'}</h2><div data-preview></div>${spec.mask?'<canvas data-mask-stage></canvas><p>白色蒙版对应选区；不选择时不会提交。</p><button data-clear-mask>清除选区</button>':''}<div data-outputs></div></main></div>`;host.append(node);const $=q=>node.querySelector(q);$('[data-back]').onclick=onBack;let catalog=[],library=[];
 async function assets(){library=(await rpc('aiyouplus_local_assets',{scope:'all'})).filter(a=>a.kind==='image'||spec.video&&a.kind==='video');const previous=[...node.querySelectorAll('[data-asset]')].map(e=>e.value);$('[data-inputs]').innerHTML=Array.from({length:spec.count},(_,i)=>`<label>${spec.video?(toolId==='motion'?(i?'动作视频':'角色图'):(i?'光照参考图':'源视频')):spec.count>1?'参考图 '+(i+1):'原图'}<select data-asset="${i}"><option value="">选择原件</option>${library.map(a=>`<option value="${escape(a.id)}">${escape(a.name)} · ${a.kind}</option>`).join('')}</select></label>`).join('');for(const e of node.querySelectorAll('[data-asset]')){if(previous[e.dataset.asset])e.value=previous[e.dataset.asset];e.onchange=()=>{selection=null;maskAsset=null;preview();update();};}}
 function chosen(){return[...node.querySelectorAll('[data-asset]')].map(e=>library.find(a=>a.id===e.value)).filter(Boolean);}
 function model(){return catalog.find(m=>m.key===$('[data-model]').value);}
 function parameters(){const out={};for(const e of node.querySelectorAll('[data-param]'))if(e.value!=='')out[e.dataset.param]=e.type==='number'?Number(e.value):e.type==='checkbox'?e.checked:e.value;return out;}
 function update(){const entry=model(),refs=chosen();let reason='';if(!entry)reason='未配置可用模型，请先在 DSH「媒体模型」中配置对应 API。';else if(refs.length!==spec.count)reason='请完整选择 '+spec.count+' 个输入原件。';else if(new Set(refs.map(a=>a.id)).size!==refs.length)reason='请为不同输入选择不同原件。';else if(!entry.inputModalities?.includes('image'))reason='模型未声明图片参考能力。';else if((entry.maxReferences??5)<spec.count)reason='模型允许的参考数量不足。';else if(spec.video&&(!entry.inputModalities?.includes('video')||!refs.some(a=>a.kind==='video')||!refs.some(a=>a.kind==='image')))reason='此功能需要一张图与一个视频，且模型须声明视频输入能力。';else if(!spec.video&&refs.some(a=>a.kind!=='image'))reason='该功能仅接受图片原件。';else if(toolId==='image-upscale'&&(!entry.parameterSchema?.width||!entry.parameterSchema?.height))reason='该模型尚未声明目标宽度与高度参数，无法保证放大输出尺寸。';else if(spec.mask&&!selection)reason='请先在原图中拖出修改选区。';else if(spec.mask&&!entry.maskSupported)reason='当前模型尚未声明并映射蒙版参数，请先完善 API 配置。';$('[data-capability]').textContent=reason||'输入与模型能力匹配，提交后会按配置的 API 生成。';$('[data-run]').disabled=busy||!!reason;return reason;}
 function renderParams(){const entry=model(),schema=entry?.parameterSchema||{};$('[data-parameters]').innerHTML=Object.entries(schema).filter(([key])=>!['prompt','width','height'].includes(key)).map(([key,s])=>`<label>${escape(key)}${s.enum?`<select data-param="${escape(key)}">${s.enum.map(v=>`<option value="${escape(v)}">${escape(v)}</option>`).join('')}</select>`:`<input data-param="${escape(key)}" type="${s.type==='boolean'?'checkbox':['integer','number'].includes(s.type)?'number':'text'}" ${s.min!==undefined?'min="'+Number(s.min)+'"':''} ${s.max!==undefined?'max="'+Number(s.max)+'"':''} value="${escape(entry?.parameters?.[key]??'')}">`}</label>`).join('')||'<p>此模型没有额外参数。</p>';update();}
 async function preview(){const ref=chosen()[0],target=$('[data-preview]');target.replaceChildren();if(!ref)return;const media=document.createElement(ref.kind==='video'?'video':'img');media.src=fileUrl(ref.path);media.alt=ref.name;media.controls=true;target.append(media);if(spec.mask){const image=new Image();image.src=fileUrl(ref.path);await image.decode();if(disposed)return;const canvas=$('[data-mask-stage]');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d');const redraw=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);if(selection){ctx.fillStyle='#ffb36b66';ctx.fillRect(selection.x,selection.y,selection.width,selection.height);ctx.strokeStyle='#fff';ctx.lineWidth=Math.max(1,canvas.width/500);ctx.strokeRect(selection.x,selection.y,selection.width,selection.height);}};let start;const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(canvas.width,(e.clientX-r.x)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.y)*canvas.height/r.height))};};canvas.onpointerdown=e=>{start=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!start)return;const p=point(e);selection={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),width:Math.abs(start.x-p.x),height:Math.abs(start.y-p.y)};redraw();};canvas.onpointerup=e=>{if(!start)return;const p=point(e);selection={x:Math.round(Math.min(start.x,p.x)),y:Math.round(Math.min(start.y,p.y)),width:Math.round(Math.abs(start.x-p.x)),height:Math.round(Math.abs(start.y-p.y))};if(selection.width<2||selection.height<2)selection=null;start=null;maskAsset=null;redraw();update();};$('[data-clear-mask]').onclick=()=>{selection=null;maskAsset=null;redraw();update();};redraw();}}
 $('[data-upload]').onchange=async e=>{try{for(const file of e.target.files){const uploaded=await uploadBrowserFile(file);try{await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}await assets();$('[data-status]').textContent='上传原件已进入 DSH 统一素材库。';}catch(error){$('[data-status]').textContent=error.message;}finally{e.target.value='';}};
 const config=await rpc('aiyouplus_model_config');catalog=Object.values(config.profiles||{}).filter(p=>p.enabled!==false&&!p.legacyArchived&&(p.authType==='none'||p.hasKey)).flatMap(p=>(p.modelCatalog||[]).filter(m=>m.kind===spec.kind).map(m=>({...m,key:encodeURIComponent(p.provider)+':'+encodeURIComponent(m.id),provider:p.provider,providerName:p.name})));$('[data-model]').innerHTML=catalog.map(m=>`<option value="${escape(m.key)}">${escape(m.name||m.id)} · ${escape(m.providerName)}</option>`).join('')||'<option value="">未配置对应媒体模型</option>';$('[data-model]').onchange=renderParams;await assets();renderParams();let requestId;
 $('[data-stop]').onclick=async()=>{if(requestId)await rpc('aiyouplus_model_stop',{requestId});$('[data-status]').textContent='已停止本地等待；远程任务是否停止由供应商决定。';};
 $('[data-run]').onclick=async()=>{const reason=update();if(reason)return;busy=true;update();$('[data-stop]').hidden=false;try{const entry=model(),refs=chosen(),prompt=$('[data-prompt]').value.trim();if(!prompt)throw Error('请填写本次处理要求');let maskPath;if(spec.mask){const image=await createImageBitmap(await(await fetch(fileUrl(refs[0].path))).blob()),mask=document.createElement('canvas');mask.width=image.width;mask.height=image.height;image.close();const ctx=mask.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,mask.width,mask.height);ctx.fillStyle='#fff';ctx.fillRect(selection.x,selection.y,selection.width,selection.height);const blob=await new Promise(r=>mask.toBlob(r,'image/png')),uploaded=await uploadBrowserFile(new File([blob],'selection-mask.png',{type:'image/png'}));try{[maskAsset]=await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});maskPath=maskAsset.path;}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}
 const layerNames=spec.layers?$('[data-layers]').value.split('\n').map(x=>x.trim()).filter(Boolean):[null];if(!layerNames.length||layerNames.length>12)throw Error('请填写 1–12 个图层名称');const outputs=[];for(const [i,layer]of layerNames.entries()){requestId=crypto.randomUUID();$('[data-status]').textContent='正在处理 '+(i+1)+' / '+layerNames.length+'…';const args={requestId,kind:spec.kind,provider:entry.provider,model:entry.id,prompt:prompt+(layer?'\n本次只输出图层「'+layer+'」，保留原画幅和位置，其他区域透明。':''),referencePaths:refs.map(a=>a.path),parameters:{...parameters(),operation:toolId},...(maskPath?{maskPath}:{}),...(toolId==='image-upscale'?{width:Number($('[data-width]').value),height:Number($('[data-height]').value)}:{})};const result=await rpc('aiyouplus_model_generate',args);if(!result.assets?.length)throw Error('API 未返回已验证入库的真实素材');if(toolId==='image-upscale'){for(const asset of result.assets){const image=await createImageBitmap(await(await fetch(fileUrl(asset.path))).blob()),actual={width:image.width,height:image.height};image.close();if(actual.width!==args.width||actual.height!==args.height)throw Error('模型返回 '+actual.width+'×'+actual.height+'，未达到请求的 '+args.width+'×'+args.height+'；原件已保存在 DSH 素材库。');}}outputs.push(...result.assets);}lastResult=outputs;$('[data-outputs]').replaceChildren();for(const output of outputs){const card=document.createElement('article'),media=document.createElement(output.kind==='video'?'video':'img');media.src=fileUrl(output.path);media.alt=output.name;media.controls=true;const download=document.createElement('a');download.href=fileUrl(output.path);download.download=output.name;download.textContent='下载原件';card.append(media,download);$('[data-outputs]').append(card);}if(['layers','cutout-repair'].includes(toolId)){const psd=document.createElement('button');psd.textContent='导出分层 PSD';psd.onclick=async()=>{psd.disabled=true;try{let width,height;const plates=[],merged=document.createElement('canvas');for(const [index,asset]of lastResult.entries()){const image=await createImageBitmap(await(await fetch(fileUrl(asset.path))).blob());if(width===undefined){width=image.width;height=image.height;if(width*height*lastResult.length>100000000)throw Error('分层图像总像素超过本机导出限制');merged.width=width;merged.height=height;}if(image.width!==width||image.height!==height){image.close();throw Error('图层原件尺寸不一致，请先统一尺寸后导出');}const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.drawImage(image,0,0);image.close();merged.getContext('2d').drawImage(canvas,0,0);plates.push({name:spec.layers?layerNames[index]||'图层 '+(index+1):'提取结果',pixels:context.getImageData(0,0,width,height).data,opacity:1,visible:true});}const bytes=window.__DSH_CREATIVE_TOOLS__.makePsd(width,height,plates,merged.getContext('2d').getImageData(0,0,width,height).data);const result=await window.__DSH_CREATIVE_TOOLS__.downloadBlob(bytes,spec.title+'-'+Date.now()+'.psd');if(!result.ok)throw Error(result.error);$('[data-status]').textContent='分层 PSD 已导出，原件已进入 DSH 素材库。';}catch(error){$('[data-status]').textContent=error.message;}finally{psd.disabled=false;}};$('[data-outputs]').append(psd);}const send=document.createElement('button');send.textContent='发送结果到当前画布';send.onclick=async()=>{send.disabled=true;try{const value=await rpc('canvas_tool_send',{assets:lastResult.map(a=>a.id)});$('[data-status]').textContent='已写入画布，保存版本 '+value.revision;}catch(error){$('[data-status]').textContent=error.message;}finally{send.disabled=false;}};$('[data-outputs]').append(send);$('[data-status]').textContent='已完成，'+outputs.length+' 个真实原件已进入 DSH 素材库。';}catch(error){$('[data-status]').textContent=error.message;}finally{busy=false;requestId=undefined;$('[data-stop]').hidden=true;update();}};
 return()=>{disposed=true;node.remove();};
}
